import React, {useEffect, useState} from 'react';
import { getObras } from '../../services/api';
import ObraCard from '../../components/ObraCard/ObraCard';
import styles from './Home.module.css';

export default function Home(){
  const [obras, setObras] = useState([]);
  const [filter, setFilter] = useState('Todos');
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);

  const fetch = async () => {
    setLoading(true);
    try{
      const res = await getObras();
      setObras(res.data || []);
    }catch(err){
      console.error(err);
      alert('Erro ao buscar obras. Verifique se o back-end está rodando.');
    }finally{
      setLoading(false);
    }
  };

  useEffect(()=>{fetch()},[]);

  const filtered = obras.filter(o => {
    if(filter !== 'Todos' && o.tipo !== filter) return false;
    if(query && !o.titulo.toLowerCase().includes(query.toLowerCase())) return false;
    return true;
  });

  return (
    <div className={styles.page}>
      <h2 className={styles.title}>Catálogo</h2>

      <div className={styles.controls}>
        <div className={styles.filters}>
          <button className="btn-neon" onClick={() => setFilter('Todos')}>Todos</button>
          <button className="btn-neon" onClick={() => setFilter('Livro')}>Livros</button>
          <button className="btn-neon" onClick={() => setFilter('Filme')}>Filmes</button>
          <button className="btn-neon" onClick={() => setFilter('Série')}>Séries</button>
        </div>

        <input
          placeholder="Buscar por título..."
          value={query}
          onChange={(e)=>setQuery(e.target.value)}
          className={styles.search}
        />
      </div>

      {loading ? <p>Carregando...</p> : (
        <div className={styles.grid}>
          {filtered.length === 0 && <p>Nenhuma obra encontrada.</p>}
          {filtered.map(o => (
            <ObraCard key={o._id || o.id} obra={o} onDeleted={fetch} />
          ))}
        </div>
      )}
    </div>
  );
}
